After obtaining context from page 5.4.4, the final 3 steps of _handle_chat are answer generation, output moderation, and storing data for caching, chat history, and subsequent quality evaluation.
Step 6 — Answer Generation using Claude ANSWER_SYSTEM_PROMPT = ( &#34;You are a retrieval-augmented assistant. Answer using ONLY the provided &#34; &#34;context. If the context does not contain the answer, say plainly that you &#34; &#34;don&#39;t have enough information — never invent facts or fill gaps from prior &#34; &#34;knowledge. Cite the source document id(s) you used. Reply in the same &#34; &#34;language as the user&#39;s question.&#34; ) def _invoke_claude(model_id, prompt, system=None, max_tokens=MAX_ANSWER_TOKENS, temperature=0.2): body = { &#34;anthropic_version&#34;: &#34;bedrock-2023-05-31&#34;, &#34;max_tokens&#34;: max_tokens, &#34;temperature&#34;: temperature, &#34;messages&#34;: [{&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: prompt}], } if system: body[&#34;system&#34;] = system response = bedrock.invoke_model(modelId=model_id, body=json.dumps(body)) payload = json.loads(response[&#34;body&#34;].read()) return &#34;&#34;.join(block.get(&#34;text&#34;, &#34;&#34;) for block in payload.get(&#34;content&#34;, [])) def _build_answer_prompt(question, parents): context_blocks = &#34;

